SELECT STABILE,SUM(CAST(LETTURA AS INT)) AS LETTURA_CONDOMINIO FROM DATI_RILEVATORI AS DA LEFT OUTER JOIN UTENZE_DETTAGLIO AS UD ON ETICHETTA=RILEVATORE LEFT OUTER JOIN UTENZE AS UT ON UT.TAGGANCIO=UD.DAGGANCIO WHERE DA.ANNO + '/' + REPLICATE('0', 2 - LEN( DA.MESE)) + DA.MESE + '/' + '01' BETWEEN '2017/01/01' AND '2017/12/31' AND ID_SCARICO = '20160209211831824125' AND STABILE='20160209211831824125' GROUP BY STABILE
SELECT STABILE,ID_CONDOMINO,DENOMINAZIONE,SUM(CAST(LETTURA AS INT)) AS LETTURA_CONDOMINO,SUM(CAST(LETTURA_ACS AS INT)) AS LETTURA_CONDOMINO_ACS,MILLESIMI_CLIMA,MILLESIMI_ACS,NUMERO_RIPARTITORI FROM ( SELECT ID_SCARICO,STABILE,RILEVATORE,LETTURA,LETTURA_ACS,DENOMINAZIONE,UT.TAGGANCIO AS ID_CONDOMINO,MILLESIMI_CLIMA,MILLESIMI_ACS, (SELECT COUNT(ETICHETTA) FROM UTENZE_DETTAGLIO WHERE DAGGANCIO=TAGGANCIO GROUP BY DAGGANCIO) AS NUMERO_RIPARTITORI FROM DATI_RILEVATORI AS DA LEFT OUTER JOIN UTENZE_DETTAGLIO AS UD ON ETICHETTA=RILEVATORE LEFT OUTER JOIN UTENZE AS UT ON UT.TAGGANCIO=UD.DAGGANCIO WHERE DA.ANNO + '/' + REPLICATE('0', 2 - LEN( DA.MESE)) + DA.MESE + '/' + '01' BETWEEN '2017/01/01' AND '2017/12/31' AND ID_SCARICO = '20160209211831824125' AND STABILE='20160209211831824125' AND STABILE IS NOT NULL ) AS TBL GROUP BY ID_CONDOMINO,DENOMINAZIONE,STABILE,MILLESIMI_CLIMA,MILLESIMI_ACS,NUMERO_RIPARTITORI ORDER BY DENOMINAZIONE

SELECT COALESCE(SUM(CONSUMI_ENERGIA_TERMICA_RISCALDAMENTO),0) AS CONSUMI_ENERGIA_TERMICA_RISCALDAMENTO,COALESCE(SUM(CONSUMI_ENERGIA_TERMICA_ACS),0) AS CONSUMI_ENERGIA_TERMICA_ACS FROM RIPARTIZIONI_UNI_DETTAGLIO WHERE DAGGANCIO ='20180117214611654686'
SELECT COALESCE(SUM(CONSUMI_ENERGIA_TERMICA_RISCALDAMENTO),0) AS CONSUMI_ENERGIA_TERMICA_RISCALDAMENTO,COALESCE(SUM(CONSUMI_ENERGIA_TERMICA_ACS),0) AS CONSUMI_ENERGIA_TERMICA_ACS FROM RIPARTIZIONI_UNI_DETTAGLIO WHERE DAGGANCIO ='20180117214611654686'
 SELECT * FROM RIPARTIZIONI_UNI_DETTAGLIO WHERE DAGGANCIO='20180117214611654686' ORDER BY DENOMINAZIONE
